/* --- Grupos automáticos --- */
function gruposDlg(t){const al=alunosAval(t);if(al.length<2)return toast('Sem alunos suficientes','aviso');const G=UI.grp=UI.grp||{n:4,tipo:'het',per:perAtual(t)};
  const nota=a=>{const v=ponderada(t,pctsFinal(t,a.id,G.per));return v==null?null:v};
  const gerar=()=>{const L=al.map(a=>({a,v:nota(a)}));const semN=L.every(x=>x.v==null);const k=Math.max(2,Math.ceil(al.length/Math.max(2,G.n)));const emb=A_=>{for(let i=A_.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[A_[i],A_[j]]=[A_[j],A_[i]]}return A_};
    let grupos=Array.from({length:k},()=>[]);
    if(G.tipo==='ale'||semN){emb(L).forEach((x,i)=>grupos[i%k].push(x))}
    else{const O=L.slice().sort((x,y)=>(y.v==null?-1:y.v)-(x.v==null?-1:x.v));
      if(G.tipo==='het'){/* serpente por níveis: cada grupo recebe alunos de todos os níveis; baralha dentro de cada volta */for(let i=0;i<O.length;i+=k){const fat=emb(O.slice(i,i+k));const ord=(i/k)%2?[...grupos.keys()].reverse():[...grupos.keys()];fat.forEach((x,j)=>grupos[ord[j]].push(x))}}
      else{O.forEach((x,i)=>grupos[Math.min(k-1,Math.floor(i/Math.ceil(O.length/k)))].push(x))}}
    return grupos.filter(g=>g.length)};
  let atual=gerar();
  const des=()=>{const med=g=>{const v=g.map(x=>x.v).filter(x=>x!=null);return v.length?v.reduce((s,x)=>s+x,0)/v.length:null};
    openDrawer('Grupos Automáticos · '+t.nome,`<div class="ed grpd"><div class="row" style="gap:10px;flex-wrap:wrap;align-items:flex-end">
      <div><label>Alunos por grupo</label><select id="gp-n">${[2,3,4,5,6].map(n=>`<option ${G.n===n?'selected':''}>${n}</option>`).join('')}</select></div>
      <div><label>Tipo</label><select id="gp-t"><option value="het" ${G.tipo==='het'?'selected':''}>Heterogéneos (níveis misturados)</option><option value="hom" ${G.tipo==='hom'?'selected':''}>Homogéneos (níveis próximos)</option><option value="ale" ${G.tipo==='ale'?'selected':''}>Aleatórios</option></select></div>
      <div><label>Com base em</label><select id="gp-p">${periodos().map(p=>`<option value="${p}" ${G.per===p?'selected':''}>${perNome(p)}</option>`).join('')}</select></div>
      <button class="btn pri" id="gp-g">${ic('refresh',15)} Gerar de Novo</button></div>
      <p class="hint">${al.every(a=>nota(a)==null)?'Ainda não há classificações: os grupos são aleatórios.':'Usa a classificação acumulada de cada aluno. Arraste um aluno para outro grupo para acertar à mão.'}</p>
      <div class="grpg">${atual.map((g,i)=>`<div class="grpc" data-gi="${i}"><h3>Grupo ${i+1} <span class="mut">${g.length} aluno${g.length>1?'s':''}${med(g)!=null?' · média '+fmtNota(t,med(g)):''}</span></h3>${g.map(x=>`<div class="grpa" draggable="true" data-ga="${x.a.id}">${avatar(x.a,30)}<span>${esc(x.a.nome)}</span>${x.v!=null?`<small>${fmtNota(t,x.v)}</small>`:''}</div>`).join('')}</div>`).join('')}</div>
      <div class="row" style="gap:8px;margin-top:12px;flex-wrap:wrap"><button class="btn" id="gp-c">${ic('paste',15)} Copiar Lista</button><button class="btn" id="gp-i">${ic('printer',15)} Imprimir</button></div></div>`);
    $('#gp-n').onchange=e=>{G.n=+e.target.value;atual=gerar();des()};$('#gp-t').onchange=e=>{G.tipo=e.target.value;atual=gerar();des()};$('#gp-p').onchange=e=>{G.per=+e.target.value;atual=gerar();des()};$('#gp-g').onclick=()=>{atual=gerar();des()};
    const txt=()=>atual.map((g,i)=>'Grupo '+(i+1)+': '+g.map(x=>x.a.nome).join(', ')).join('\n');
    $('#gp-c').onclick=()=>{try{navigator.clipboard.writeText(txt());toast('Grupos copiados','ok')}catch(_){toast('Não foi possível copiar','erro')}};
    $('#gp-i').onclick=()=>{const w=window.open('','_blank');if(!w)return toast('O browser bloqueou a janela de impressão','erro');w.document.write('<title>Grupos · '+esc(t.nome)+'</title><body style="font:14px system-ui,sans-serif;padding:24px"><h2>Grupos · '+esc(t.nome)+' · '+esc(t.disciplina||'')+'</h2>'+atual.map((g,i)=>'<h3 style="margin:14px 0 4px">Grupo '+(i+1)+'</h3><ol style="margin:0">'+g.map(x=>'<li>'+esc(x.a.nome)+'</li>').join('')+'</ol>').join('')+'</body>');w.document.close();w.focus();w.print()};
    let arr=null;$$('#dw-b .grpa').forEach(e=>{e.ondragstart=ev=>{arr=e.dataset.ga;ev.dataTransfer.effectAllowed='move'}});$$('#dw-b .grpc').forEach(c=>{c.ondragover=ev=>{ev.preventDefault();c.classList.add('ov')};c.ondragleave=()=>c.classList.remove('ov');c.ondrop=ev=>{ev.preventDefault();if(!arr)return;let it=null;atual.forEach(g=>{const i=g.findIndex(x=>x.a.id===arr);if(i>=0)it=g.splice(i,1)[0]});if(it)atual[+c.dataset.gi].push(it);atual=atual.filter(g=>g.length);arr=null;des()}})};
  des()}
/* --- Simulador de nota --- */
function simuladorDlg(t){const al=alunosAval(t);const sec=isSec(t);const U=UI.sim=UI.sim||{per:perAtual(t),alvo:sec?10:50};
  const des=()=>{const linhas=al.map(a=>{let A_=0,B=0,W=0;t.dominios.forEach(d=>{const w=+d.peso||0;if(!w)return;const v=t.instrumentos.filter(i=>+i.periodo===+U.per).map(i=>instDom(i,a.id,d.id)).filter(Boolean).map(x=>x.pct);const n=v.length,sm=v.reduce((p,c)=>p+c,0);A_+=w*sm/(n+1);B+=w/(n+1);W+=w});
      const atual=ponderada(t,pctsPer(t,a.id,U.per));const alvo=(sec?U.alvo/20:U.alvo/100);const x=B?(alvo*W-A_)/B:null;return {a,atual,x}});
    openDrawer('Simulador de Nota · '+t.nome,`<div class="ed simd"><div class="row" style="gap:10px;flex-wrap:wrap;align-items:flex-end"><div><label>${perW()}</label><select id="sm-p">${periodos().map(p=>`<option value="${p}" ${U.per===p?'selected':''}>${perNome(p)}</option>`).join('')}</select></div>
      <div><label>Objetivo (${sec?'valores':'%'})</label><input id="sm-a" type="number" inputmode="decimal" min="0" max="${sec?20:100}" step="${sec?0.5:1}" value="${U.alvo}" style="width:110px"></div>
      <div class="row" style="gap:6px">${(sec?[9.5,10,14,18]:[50,70,90]).map(v=>`<button class="btn sm" data-sma="${v}">${String(v).replace('.',',')}${sec?'':'%'}</button>`).join('')}</div></div>
      <p class="hint">O que cada aluno precisa de tirar no <b>próximo elemento de avaliação</b> (a contar para todos os domínios) para a nota do ${perW().toLowerCase()} chegar ao objetivo.</p>
      <table class="lst simt"><thead><tr><th>Aluno</th><th>Nota atual</th><th>Precisa de</th></tr></thead><tbody>${linhas.map(({a,atual,x})=>{let c='',tx='—';if(x!=null){if(x<=0){c='ok';tx='Já garantido'}else if(x>1.0001){c='bad';tx='Não chega só com um elemento ('+fmtNota(t,x)+')'}else{c=x>.75?'warn':'';tx=fmtNota(t,x)+(sec?' valores':'')}}return `<tr><td>${esc(numAl(a))}. ${esc(a.nome)}</td><td class="c">${atual==null?'—':fmtNota(t,atual)}</td><td class="c simx ${c}"><b>${tx}</b></td></tr>`}).join('')}</tbody></table></div>`);
    $('#sm-p').onchange=e=>{U.per=+e.target.value;des()};$('#sm-a').onchange=e=>{const v=parseFloat(String(e.target.value).replace(',','.'));if(!isNaN(v)){U.alvo=v;des()}};$$('[data-sma]').forEach(b=>b.onclick=()=>{U.alvo=+b.dataset.sma;des()})};des()}
